import{_ as n,l as o,o as e,c as l,v as i,p as s,x as r,d,i as u,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"覆盖引导 fuzzing","description":"","frontmatter":{"title":"覆盖引导 fuzzing","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coverage-guided-fuzzing.md","filePath":"cs/coverage-guided-fuzzing.md","lastUpdated":1789023840000}'),h={name:"cs/coverage-guided-fuzzing.md"};function p(f,a,z,_,A,E){const t=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="覆盖引导-fuzzing" tabindex="-1">覆盖引导 fuzzing <a class="header-anchor" href="#覆盖引导-fuzzing" aria-label="Permalink to &quot;覆盖引导 fuzzing&quot;">​</a></h1><div class="epigraph"><p>随机输入若能看见「覆盖了新边」，就能把变异压向未走过的分支。AFL 一类工具把程序当仪器，而不是当证明器：找到的是崩溃，不是无洞。</p><footer>—— Zalewski, American Fuzzy Lop；libFuzzer；Manès et al., The Art, Science, and Engineering of Fuzzing, TSE</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/memory-safe-languages">内存安全语言</a>承认遗留 C 仍在。缺口是<strong>如何便宜地找崩溃</strong>：覆盖引导 fuzz。不把符号执行提前讲完。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工测试到不了深层分支。插桩记录边覆盖，语料库保留能长覆盖的输入，变异（位翻转、字典）围着它们转。缺口是：无崩溃不等于安全；覆盖不是功能正确。</p><h3 id="要有预言" tabindex="-1">要有预言 <a class="header-anchor" href="#要有预言" aria-label="Permalink to &quot;要有预言&quot;">​</a></h3><p>只看信号量崩溃会漏逻辑洞。Sanitizer 下一课把更多未定义变成崩溃。</p><p><span class="marginnote">AFL；libFuzzer。本课不提供对第三方产品的 fuzz 作战计划。种子语料来自合法文件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：语料→变异→执行→覆盖反馈→保留。指出结构感知（协议、语法）提高密度。对照符号执行：精确路径条件，更贵。</p>',12)),(e(),s(c,null,{default:r(()=>[u(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORP%5B%22%E8%AF%AD%E6%96%99%22%5D%20--%3E%20MUT%5B%22%E5%8F%98%E5%BC%82%22%5D%0A%20%20MUT%20--%3E%20RUN%5B%22%E6%8F%92%E6%A1%A9%E6%89%A7%E8%A1%8C%22%5D%0A%20%20RUN%20--%3E%20COV%5B%22%E6%96%B0%E8%A6%86%E7%9B%96%3F%22%5D%0A%20%20COV%20--%3E%20CORP%0A%20%20RUN%20--%3E%20CRASH%5B%22%E5%B4%A9%E6%BA%83%E5%85%A5%E6%A1%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现课把「利用课的洞」变成可回归的测试输入。下一课 KLEE：用约束求解补随机走不到的分支。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写武器化崩溃。符号执行下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遗留 C 要用自动发现。</li><li>覆盖反馈引导变异；崩溃是信号。</li><li>无崩溃 ≠ 无洞。</li><li>下一课符号执行 KLEE。</li><li>出处：Zalewski, AFL；libFuzzer；Manès et al., TSE。</li></ul>',8))])}const b=n(h,[["render",p]]);export{m as __pageData,b as default};
